import { STRINGS } from "./i18n.js";

/**
 * Editor-only copy: every e_ / ed_ / f_ key the visual editors read, in
 * English and Belgian Dutch. It ships in the lazy editors chunk (imported
 * first by src/editors.js) and joins the shared table at load, so t(), tr()
 * and localize() read it exactly like a key in i18n.js.
 *
 * A key a CARD renders (an aria label, a state word) belongs in i18n.js,
 * never here: a viewed dashboard never loads this file, and t() would print
 * the bare key. test/i18n-editors.test.js guards both halves.
 *
 * f_<name> labels a field that has no label of its own.
 */
